// 解析RSS内容并提取新闻文章
const feedparser = require('feedparser');
const stream = require('stream');

// 处理所有RSS源的响应
const allArticles = [];

for (const item of $input.all()) {
  try {
    const xmlData = item.json.data || item.json;

    // 简单的XML解析 - 提取基本信息
    const titleMatch = xmlData.match(/<title[^>]*><!\[CDATA\[([^\]]+)\]\]><\/title>|<title[^>]*>([^<]+)<\/title>/g);
    const linkMatch = xmlData.match(/<link[^>]*>([^<]+)<\/link>/g);
    const descMatch = xmlData.match(/<description[^>]*><!\[CDATA\[([^\]]+)\]\]><\/description>|<description[^>]*>([^<]+)<\/description>/g);
    const dateMatch = xmlData.match(/<pubDate[^>]*>([^<]+)<\/pubDate>/g);

    if (titleMatch && linkMatch) {
      // 提取第一个匹配项（通常是标题）
      for (let i = 1; i < Math.min(titleMatch.length, 6); i++) {
        const title = titleMatch[i]?.replace(/<[^>]+>/g, '').replace(/<!\[CDATA\[|\]\]>/g, '').trim();
        const link = linkMatch[i]?.replace(/<[^>]+>/g, '').trim();
        const description = descMatch && descMatch[i] ? descMatch[i].replace(/<[^>]+>/g, '').replace(/<!\[CDATA\[|\]\]>/g, '').trim() : '';
        const pubDate = dateMatch && dateMatch[i] ? dateMatch[i].replace(/<[^>]+>/g, '').trim() : '';

        if (title && link && title.length > 10) {
          // 检查是否包含交易相关关键词
          const tradingKeywords = ['stock', 'market', 'trading', 'shares', 'investment', 'economy', 'fed', 'federal reserve', 'earnings', 'revenue', 'profit', 'loss', 'nasdaq', 'dow', 'sp500', 's&p'];
          const isRelevant = tradingKeywords.some(keyword => 
            title.toLowerCase().includes(keyword) || 
            description.toLowerCase().includes(keyword)
          );

          if (isRelevant) {
            allArticles.push({
              title: title,
              url: link,
              summary: description,
              published_at: pubDate,
              source: item.json.url || 'RSS Feed',
              relevance_score: Math.random() * 10, // 临时评分
              extracted_at: new Date().toISOString()
            });
          }
        }
      }
    }
  } catch (error) {
    console.log('Error parsing RSS:', error.message);
  }
}

// 去重处理
const uniqueArticles = [];
const seenUrls = new Set();

for (const article of allArticles) {
  if (!seenUrls.has(article.url)) {
    seenUrls.add(article.url);
    uniqueArticles.push(article);
  }
}

console.log(`Processed ${uniqueArticles.length} unique articles`);

return uniqueArticles.map(article => ({ json: article }));
